100|    msg_text[JSON_ERROR_TEXT_LENGTH - 1] = '\0';
101|    va_end(ap);
102|
103|    if (lex) {
104|        const char *saved_text = strbuffer_value(&lex->saved_text);
105|
106|        line = lex->stream.line;
107|        col = lex->stream.column;
108|        pos = lex->stream.position;
